// Manual addition using bit operations
__attribute__((noinline)) long long manual_add(long long a, long long b) {
    while (b != 0) {
        long long carry = a & b;
        a = a ^ b;
        b = carry << 1;
    }
    return a;
}

// Manual subtraction using bit operations
__attribute__((noinline)) long long manual_sub(long long a, long long b) {
    while (b != 0) {
        long long borrow = (~a) & b;
        a = a ^ b;
        b = borrow << 1;
    }
    return a;
}

// Manual XOR processing bit by bit
__attribute__((noinline)) long long manual_xor(long long a, long long b) {
    long long result = 0;
    long long bit_position = 1;
    
    // Process each bit individually
    for (int i = 0; i < 64; i++) {
        // Extract bit at position i from both numbers
        long long bit_a = (a & bit_position) ? 1 : 0;
        long long bit_b = (b & bit_position) ? 1 : 0;
        
        // Manual XOR: result is 1 if bits are different, 0 if same
        long long xor_bit = 0;
        if ((bit_a == 1 && bit_b == 0) || (bit_a == 0 && bit_b == 1)) {
            xor_bit = 1;
        }
        
        // Set the result bit if XOR is 1
        if (xor_bit == 1) {
            result = result | bit_position;
        }
        
        // Move to next bit position
        bit_position = bit_position << 1;
        
        // Break early if both numbers have no more bits to process
        if (a < bit_position && b < bit_position) {
            break;
        }
    }
    
    return result;
}

// Lua wrapper functions
static int lua_add(lua_State *L) {
    long long a = luaL_checkinteger(L, 1);
    long long b = luaL_checkinteger(L, 2);
    lua_pushinteger(L, manual_add(a, b));
    return 1;
}

static int lua_sub(lua_State *L) {
    long long a = luaL_checkinteger(L, 1);
    long long b = luaL_checkinteger(L, 2);
    lua_pushinteger(L, manual_sub(a, b));
    return 1;
}

static int lua_xor(lua_State *L) {
    long long a = luaL_checkinteger(L, 1);
    long long b = luaL_checkinteger(L, 2);
    lua_pushinteger(L, manual_xor(a, b));
    return 1;
}

int main() {
    char input[33 + 1];
    printf("Flag: ");
    scanf("%s", input);

    if (strlen(input) != 33) {
        printf("WRONG\n");
        return 1;
    }

    for (int i = 0; i < 1163; i++) {
        if (lua_codes[i] == '*') {
            for (int j = 0; j < 33; j++) {
                lua_codes[i + j] = input[j];
            }
            break;
        }
    }

    lua_State *L = luaL_newstate();
    
    if (L == NULL) {
        return 1;
    }
    
    luaL_openlibs(L);

    // lua_register(L, "qwx7z", lua_add);
    // lua_register(L, "m9kp2", lua_sub);
    // lua_register(L, "j3s5l", lua_xor);
    lua_register(L, s_lua_add, lua_add);
    lua_register(L, s_lua_sub, lua_sub);
    lua_register(L, s_lua_xor, lua_xor);

    int result = luaL_dostring(L, lua_codes);
    
    if (result != LUA_OK) {
        lua_close(L);
        return 1;
    }
    
    lua_close(L);
    return 0;
}

